DO $$ DECLARE def text; BEGIN
 SELECT pg_get_functiondef('app_private.quality_merge_manifest(uuid,uuid)'::regprocedure) INTO def;
 def:=replace(def,'FROM public.documents WHERE child_id IN(SELECT id FROM public.children WHERE beneficiary_id=_duplicate)','FROM public.documents WHERE child_id=_duplicate');
 def:=replace(def,'blocked:=EXISTS(SELECT 1 FROM public.vulnerability_assessments WHERE beneficiary_id=_duplicate);', 'FOR rel IN SELECT * FROM (VALUES (''donation_intents'',''target_beneficiary_id''),(''beneficiary_relationships'',''beneficiary_a_id''),(''beneficiary_relationships'',''beneficiary_b_id''),(''beneficiary_siblings'',''sibling_id'')) AS x(table_name,column_name) LOOP EXECUTE format(''SELECT coalesce(jsonb_agg(id ORDER BY id),''''[]''''::jsonb) FROM public.%I WHERE %I=$1'',rel.table_name,rel.column_name) INTO ids USING _duplicate; IF jsonb_array_length(ids)>0 THEN links:=links||jsonb_build_array(jsonb_build_object(''table'',rel.table_name,''column'',rel.column_name,''ids'',ids,''action'',''repoint_preserving_ids'')); END IF; END LOOP; SELECT coalesce(jsonb_agg(id ORDER BY id),''[]''::jsonb) INTO ids FROM public.me_form_submissions WHERE _duplicate=ANY(beneficiary_ids); IF jsonb_array_length(ids)>0 THEN links:=links||jsonb_build_array(jsonb_build_object(''table'',''me_form_submissions'',''column'',''beneficiary_ids'',''ids'',ids,''action'',''blocked_immutable'')); END IF; blocked:=EXISTS(SELECT 1 FROM public.vulnerability_assessments WHERE beneficiary_id=_duplicate) OR EXISTS(SELECT 1 FROM public.documents WHERE child_id=_duplicate) OR EXISTS(SELECT 1 FROM public.me_form_submissions WHERE _duplicate=ANY(beneficiary_ids));');
 def:=replace(def,'Immutable assessments cannot be reassigned. Resolve through reviewed history migration; no records will be changed.','Immutable assessment, form or legacy file history requires a reviewed migration; no records will be changed.'); EXECUTE def;
 SELECT pg_get_functiondef('app_private.reviewed_beneficiary_merge(uuid,uuid,uuid,text,jsonb)'::regprocedure) INTO def;
 def:=replace(def,'''UPDATE public.%I SET beneficiary_id=$1 WHERE beneficiary_id=$2'',link->>''table''','''UPDATE public.%I SET %I=$1 WHERE %I=$2'',link->>''table'',link->>''column'',link->>''column''');
 def:=replace(def,'UPDATE public.children SET beneficiary_id=_canonical WHERE beneficiary_id=_duplicate;','');
 EXECUTE def;
 SELECT pg_get_functiondef('app_private.quality_rule_failed(uuid,uuid)'::regprocedure) INTO def;
 def:=replace(def,'ELSIF r.template_key=''need_without_assessment'' THEN SELECT n.beneficiary_id INTO bid FROM public.beneficiary_needs n WHERE n.id=_record AND n.organization_id=r.organization_id;
 IF bid IS NULL THEN SELECT c.beneficiary_id,(c.deleted_at IS NULL AND c.status IN (''active'',''expired'') AND c.expires_at<current_date) INTO bid,expired FROM public.consent_documents c WHERE c.id=_record AND c.organization_id=r.organization_id; END IF;','ELSIF r.template_key=''need_without_assessment'' THEN SELECT n.beneficiary_id INTO bid FROM public.beneficiary_needs n WHERE n.id=_record AND n.organization_id=r.organization_id;'); EXECUTE def;
END $$;
NOTIFY pgrst,'reload schema';